-- STEP B — Akure Humboldt Kolleg 2027 release (GENERATED by scripts/build-release-sql.sh; do not edit)
-- Applies 20261118000100 (blind review) and 20261118000200 (least privilege).
-- NOT compatible with the previously deployed app: promote the new deployment
-- immediately after COMMIT. One transaction: any failed check rolls back.
begin;

create temporary table _release_pre on commit drop as
select s.demo_mode, s.registration_open, s.submissions_open, s.registration_deadline, s.abstract_deadline,
       (select count(*) from public.registrations) as registrations,
       (select count(*) from public.abstracts) as abstracts,
       (select count(*) from public.reviews) as reviews,
       (select count(*) from public.review_assignments) as assignments,
       (select count(*) from public.user_roles) as user_roles
from public.conference_settings s where s.id = 1;

do $pre$ begin
  if not (select demo_mode from _release_pre) then
    raise exception 'STEP B precondition failed: demo_mode must be true (pre-launch test mode)';
  end if;
  if to_regprocedure('public.grant_conference_reviewer(text)') is null then
    raise exception 'STEP B precondition failed: STEP A has not been applied';
  end if;
end $pre$;

-- ===== begin 20261118000100_blind_review_and_reviewer_revocation.sql =====
-- Blind review and reviewer revocation. Tightening only; no data is changed.
--
-- Problem fixed: the abstracts SELECT policy let anyone with a review assignment
-- read the FULL abstract row (author name, email, institution, co-authors)
-- directly through the API, and it did not check the reviewer role, so a
-- reviewer whose role had been removed kept that access.
--
-- After this migration:
--   * Reviewers no longer read public.abstracts directly.
--   * They read their assignments through public.conference_reviewer_assignments(),
--     which returns only blind fields and requires a CURRENT reviewer role.
--   * Attachment access for reviewers also requires a current reviewer role
--     (unchanged rule, now evaluated through a definer helper because the
--     storage policy can no longer see abstracts rows as the reviewer).
--   * Authors and organisers keep exactly the access they had.

-- 1. Authors and organisers only.
drop policy if exists abstract_owner_admin_reviewer_read on public.abstracts;
drop policy if exists abstract_owner_or_admin_read on public.abstracts;
create policy abstract_owner_or_admin_read on public.abstracts for select to authenticated
using (user_id = (select auth.uid()) or private.has_role('organiser'));

-- 2. Blind assignment list for the calling reviewer.
create or replace function public.conference_reviewer_assignments()
returns table(
  assignment_id uuid, abstract_id uuid, serial_number bigint, title text, body text,
  track int, keywords text[], presentation_type text, status text, is_demo boolean, file_path text
)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not private.has_role('reviewer') then
    raise exception 'reviewer role required' using errcode = '42501';
  end if;
  return query
    select ra.id, a.id, a.serial_number, a.title, a.body, a.track, a.keywords,
           a.presentation_type, a.status, a.is_demo, a.file_path
    from public.review_assignments ra
    join public.abstracts a on a.id = ra.abstract_id
    where ra.reviewer_id = (select auth.uid())
    order by ra.assigned_at;
end$$;
revoke all on function public.conference_reviewer_assignments() from public, anon;
grant execute on function public.conference_reviewer_assignments() to authenticated;

-- 3. Attachment access. file_path is returned above because the signed link the
--    reviewer receives contains it anyway; its folder is an opaque account id that
--    reviewers have no way to resolve to a person.
create or replace function private.reviewer_can_read_file(p_name text)
returns boolean
language sql stable security definer set search_path = '' as $$
  select private.has_role('reviewer') and exists (
    select 1 from public.abstracts a
    join public.review_assignments ra on ra.abstract_id = a.id
    where a.file_path = p_name and ra.reviewer_id = (select auth.uid())
  )
$$;
revoke all on function private.reviewer_can_read_file(text) from public, anon;
grant execute on function private.reviewer_can_read_file(text) to authenticated;

drop policy if exists abstract_files_assigned_reviewer_read on storage.objects;
create policy abstract_files_assigned_reviewer_read on storage.objects for select to authenticated
using (bucket_id = 'abstract-files' and private.reviewer_can_read_file(name));

-- 4. The settings trigger needs no elevated rights.
alter function private.stamp_conference_settings() security invoker;

-- ===== end 20261118000100_blind_review_and_reviewer_revocation.sql =====

-- ===== begin 20261118000200_least_privilege_grants_and_role_policies.sql =====
-- Least-privilege reconciliation with the live database (audit of 2026-11-18,
-- docs/audit/2026-11-18_live_database_drift_findings.md).
--
-- Live findings addressed:
--   1. anon and authenticated hold ALL table privileges (incl. TRUNCATE, which
--      RLS does not govern) on the conference tables.
--   2. Table-wide UPDATE on conference_settings lets organisers change demo_mode
--      through the API, defeating the intended column-only grant.
--   3. Extra user_roles policies (roles_organiser_add_reviewer /
--      roles_organiser_remove_reviewer) allow direct organiser role writes,
--      bypassing the audited grant/revoke functions.
--
-- Approach: revoke everything from the client roles on the nine conference
-- tables, then grant back exactly what the application's workflows use. RLS
-- policies stay the row-level gate; these grants are the column/operation gate.
-- No rows are changed. service_role and postgres are not touched.
-- Idempotent: safe to re-run.

------------------------------------------------------------------------------
-- 1. Reset client-role table privileges on the conference tables
------------------------------------------------------------------------------
revoke all on table
  public.user_roles, public.registrations, public.abstracts, public.review_assignments,
  public.reviews, public.speakers, public.sessions, public.public_abstracts, public.conference_settings
from anon, authenticated;

------------------------------------------------------------------------------
-- 2. Grant back exactly what each workflow needs
------------------------------------------------------------------------------
-- Public website (signed out): published programme, speakers, released
-- abstracts, and the launch state shown on the registration pages.
grant select on public.speakers, public.sessions, public.public_abstracts, public.conference_settings to anon;

-- Signed-in users. Comments name the workflow; RLS decides whose rows.
grant select on public.user_roles to authenticated;                         -- "am I staff?"; organisers list roles
grant select, insert on public.registrations to authenticated;              -- register; no edits after submission
grant select, insert on public.abstracts to authenticated;                  -- submit; read own (organisers read all)
grant update (status, is_published, decision_at)                            -- organiser decisions only; author text,
  on public.abstracts to authenticated;                                     -- email and is_demo stay immutable
grant select, insert, delete on public.review_assignments to authenticated; -- organiser assigns / unassigns
grant update (abstract_id, reviewer_id)                                     -- needed by the idempotent upsert
  on public.review_assignments to authenticated;                            -- (no UPDATE policy: rows never change)
grant select, insert on public.reviews to authenticated;                    -- reviewer saves a review
grant update (assignment_id, reviewer_id, relevance, rigour, clarity, impact, recommendation, comments, updated_at)
  on public.reviews to authenticated;                                       -- reviewer edits own review (upsert)
grant select, insert, update, delete on public.speakers, public.sessions to authenticated;  -- organiser content admin
grant select on public.public_abstracts to authenticated;
grant select on public.conference_settings to authenticated;
grant update (registration_open, submissions_open, registration_deadline, abstract_deadline, updated_at)
  on public.conference_settings to authenticated;                          -- Launch controls; NOT demo_mode

------------------------------------------------------------------------------
-- 3. Reviewer roles change only through the audited functions
------------------------------------------------------------------------------
drop policy if exists roles_organiser_add_reviewer on public.user_roles;
drop policy if exists roles_organiser_remove_reviewer on public.user_roles;
-- (user_roles now has SELECT only for clients, so even a re-created write
--  policy would have no effect without a fresh, reviewed GRANT.)

------------------------------------------------------------------------------
-- 4. SECURITY DEFINER functions: never executable by PUBLIC or anon
------------------------------------------------------------------------------
do $$
declare f regprocedure;
begin
  for f in
    select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname in ('public', 'private') and p.prosecdef
  loop
    execute format('revoke execute on function %s from public, anon', f);
  end loop;
end $$;

------------------------------------------------------------------------------
-- 5. Default privileges: deliberately NARROW guarantee.
--
--    What this does: removes the SCHEMA-LEVEL defaults that Supabase sets on schema
--    public for objects created by the role running this migration (postgres), so:
--      * new TABLES in public get no automatic grants for anon/authenticated;
--      * new FUNCTIONS in public lose Supabase's schema-level grants.
--
--    What it does NOT do: make new functions private. PostgreSQL grants EXECUTE on
--    every new function to PUBLIC, and the live project also has a GLOBAL default
--    EXECUTE grant to authenticated. A schema-level REVOKE cannot override either,
--    and changing global defaults would also affect Supabase-managed schemas, so
--    this migration intentionally leaves global defaults alone.
--
--    Control instead: every migration that creates a function in public must
--    REVOKE EXECUTE explicitly (from public, anon and, unless intended, authenticated).
--    CI enforces it: supabase/tests/15_privilege_matrix.sql fails if any function
--    in public is executable by anon, or by authenticated without being on the
--    reviewed allowlist, and 16_default_privileges.sql records the real defaults.
------------------------------------------------------------------------------
alter default privileges in schema public revoke all on tables from anon, authenticated;
alter default privileges in schema public revoke execute on functions from anon, authenticated;

-- ===== end 20261118000200_least_privilege_grants_and_role_policies.sql =====

do $post$
declare p record; bad text;
begin
  select * into p from _release_pre;
  if (select (demo_mode, registration_open, submissions_open, registration_deadline, abstract_deadline)
             is distinct from (p.demo_mode, p.registration_open, p.submissions_open, p.registration_deadline, p.abstract_deadline)
      from public.conference_settings where id = 1) then
    raise exception 'STEP B postcondition failed: launch settings changed';
  end if;
  if (select count(*) from public.registrations) <> p.registrations or (select count(*) from public.abstracts) <> p.abstracts
     or (select count(*) from public.reviews) <> p.reviews or (select count(*) from public.review_assignments) <> p.assignments
     or (select count(*) from public.user_roles) <> p.user_roles then
    raise exception 'STEP B postcondition failed: row counts changed';
  end if;
  -- No dangerous table privileges for client roles on the conference tables.
  select string_agg(r || ' ' || pr || ' ' || tb, ', ') into bad
  from unnest(array['anon','authenticated']) r,
       unnest(array['TRUNCATE','REFERENCES','TRIGGER']) pr,
       unnest(array['user_roles','registrations','abstracts','review_assignments','reviews','speakers','sessions','public_abstracts','conference_settings']) tb
  where has_table_privilege(r, 'public.' || tb, pr);
  if bad is not null then raise exception 'STEP B postcondition failed: client privileges remain: %', bad; end if;
  if has_column_privilege('authenticated', 'public.conference_settings', 'demo_mode', 'UPDATE')
     or has_column_privilege('anon', 'public.conference_settings', 'demo_mode', 'UPDATE') then
    raise exception 'STEP B postcondition failed: demo_mode is still updatable by a client role';
  end if;
  if exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'user_roles' and cmd in ('INSERT','UPDATE','DELETE','ALL')) then
    raise exception 'STEP B postcondition failed: a client write policy remains on user_roles';
  end if;
  if exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'abstracts' and policyname = 'abstract_owner_admin_reviewer_read') then
    raise exception 'STEP B postcondition failed: reviewer branch of the abstracts read policy remains';
  end if;
  -- Exact-signature function exposure.
  select string_agg(f, ', ') into bad from (
    select format('%s.%s(%s)', n.nspname, pp.proname, oidvectortypes(pp.proargtypes)) f
    from pg_proc pp join pg_namespace n on n.oid = pp.pronamespace
    where n.nspname = 'public' and has_function_privilege('authenticated', pp.oid, 'EXECUTE')
      and not exists (select 1 from pg_depend d where d.classid = 'pg_proc'::regclass and d.objid = pp.oid and d.deptype = 'e')
      and pp.oid not in ('public.conference_reviewer_assignments()'::regprocedure, 'public.conference_reviewer_directory()'::regprocedure,
                         'public.find_conference_account(text)'::regprocedure, 'public.grant_conference_reviewer(text)'::regprocedure,
                         'public.revoke_conference_reviewer(uuid)'::regprocedure)) x;
  if bad is not null then raise exception 'STEP B postcondition failed: unapproved public functions executable by authenticated: %', bad; end if;
  select string_agg(format('%s.%s(%s)', n.nspname, pp.proname, oidvectortypes(pp.proargtypes)), ', ') into bad
  from pg_proc pp join pg_namespace n on n.oid = pp.pronamespace
  where n.nspname = 'public' and has_function_privilege('anon', pp.oid, 'EXECUTE')
    and not exists (select 1 from pg_depend d where d.classid = 'pg_proc'::regclass and d.objid = pp.oid and d.deptype = 'e');
  if bad is not null then raise exception 'STEP B postcondition failed: public functions executable by anon: %', bad; end if;
  raise notice 'STEP B verified: settings and row counts unchanged; least-privilege grants, blind review and exact function exposure in place';
end $post$;
commit;
